CREATE TABLE IF NOT EXISTS `dpn_medical_invoices` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`issuer_cid` varchar(64) NULL,`category` varchar(64) NOT NULL,`reason` varchar(255) NOT NULL,`total_amount` int NOT NULL,`covered_amount` int NOT NULL DEFAULT 0,`patient_amount` int NOT NULL,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),`paid_at` datetime NULL,PRIMARY KEY (`id`),KEY `idx_invoice_patient` (`patient_cid`),KEY `idx_invoice_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
